using Handler = std::function<Response(const Request &)>;

const std::unordered_map<std::string, Handler> table{
    {"get", get_handler}, {"put", put_handler},
};

Response dispatch(const std::string &key, const Request &req) {
    auto it = table.find(key);
    if (it == table.end()) throw std::runtime_error("unknown op: " + key);
    return it->second(req);
}

