static const std::array execute_table = { &&do_push, &&do_add, &&do_halt };
#define DISPATCH() goto *execute_table[static_cast<std::size_t>(*ip++)]

DISPATCH();
do_push:  stack[sp++] = *ip++; DISPATCH();
do_add:   stack[sp - 2] += stack[--sp]; DISPATCH();
do_halt:  return stack[sp - 1];
